command:
set -eu; . /root/vault-transit-admin.env; export VAULT_ADDR VAULT_CACERT VAULT_TOKEN; vault secrets enable transit >/dev/null; vault write -f transit/keys/raft-auto-unseal >/dev/null; cat > /root/raft-auto-unseal-policy.hcl <<'POLICY'
path "transit/encrypt/raft-auto-unseal" {
  capabilities = ["update"]
}
path "transit/decrypt/raft-auto-unseal" {
  capabilities = ["update"]
}
POLICY
vault policy write raft-auto-unseal /root/raft-auto-unseal-policy.hcl >/dev/null; umask 077; for n in node2 node3 node4; do vault token create -policy=raft-auto-unseal -orphan -period=768h -display-name="$n-auto-unseal" -format=json > "/root/$n-seal-token.json"; python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["auth"]["client_token"])' "/root/$n-seal-token.json" > "/root/$n-seal-token"; chmod 0600 "/root/$n-seal-token.json" "/root/$n-seal-token"; done; vault secrets list -format=json | python3 -c 'import json,sys; d=json.load(sys.stdin); print("transit_type="+d["transit/"]["type"]); print("transit_version="+str(d["transit/"]["options"].get("version","n/a")))'; vault read -format=json transit/keys/raft-auto-unseal | python3 -c 'import json,sys; d=json.load(sys.stdin)["data"]; print("key_name=%s type=%s latest_version=%s supports_encryption=%s supports_decryption=%s"%(d["name"],d["type"],d["latest_version"],str(d["supports_encryption"]).lower(),str(d["supports_decryption"]).lower()))'; for n in node2 node3 node4; do python3 -c 'import json,sys; a=json.load(open(sys.argv[1]))["auth"]; print(sys.argv[2]+" renewable="+str(a["renewable"]).lower()+" period="+str(a.get("period",0))+" policies="+",".join(a["policies"]))' "/root/$n-seal-token.json" "$n"; done

